/** Corpo de template de comunicação (aniversário / conclusão) gerenciado no MetaAdminGeral. */
type ComunicacaoTemplate = { body: string; variables: string[] };

/** Substitui variáveis {chave} no corpo de um template de comunicação. */
function renderComunicacaoTemplate(body: string, vars: Record<string, string>): string {
  let out = body;
  for (const [key, value] of Object.entries(vars)) {
    out = out.split(`{${key}}`).join(value);
  }
  return out;
}

