  const [loadingMensagensResidentes, setLoadingMensagensResidentes] = useState(false);
  const [mensagensNaoLidasResidentes, setMensagensNaoLidasResidentes] = useState(0);
  const [activeTabMensagens, setActiveTabMensagens] = useState<'enviadas' | 'recebidas'>('enviadas');
  const [showMensagemModal, setShowMensagemModal] = useState(false);
  const [mensagemSelecionada, setMensagemSelecionada] = useState<MensagemResidenteParaAdmin | null>(null);
  const [showMensagemEnviadaModal, setShowMensagemEnviadaModal] = useState(false);
  const [mensagemEnviadaSelecionada, setMensagemEnviadaSelecionada] = useState<Mensagem | null>(null);
  
  // Estados para modais de cadastro
  const [showCadastrarResidenteModal, setShowCadastrarResidenteModal] = useState(false);
  const [showCadastrarLocalModal, setShowCadastrarLocalModal] = useState(false);
  const [showCadastrarServicoModal, setShowCadastrarServicoModal] = useState(false);
  const [showCadastrarPacienteModal, setShowCadastrarPacienteModal] = useState(false);
  
  // Estados para paciente
  const [pacientes, setPacientes] = useState<PacienteCompleto[]>([]);

  // Event listeners para arrastar o marcador de IMC (mouse)
  useEffect(() => {
    if (!isDraggingIMC || !pacienteArrastandoIMC) return;

    const handleMouseMove = (e: MouseEvent) => {
      const barraRef = barraIMCRef.current[pacienteArrastandoIMC];
      if (!barraRef) return;
      
      const rect = barraRef.getBoundingClientRect();
      const x = e.clientX - rect.left;
      // Trava nas extremidades: limitar entre 0% e 100%
      const percentual = Math.max(0, Math.min(100, (x / rect.width) * 100));
      
      // Buscar dados do paciente
      const paciente = pacientes.find(p => p.id === pacienteArrastandoIMC);
      if (!paciente) return;
      
      const medidasIniciais = paciente.dadosClinicos?.medidasIniciais;
      const alturaCm = medidasIniciais?.altura;
      const alturaMetros = alturaCm && typeof alturaCm === 'number' && alturaCm > 0 ? alturaCm / 100 : null;
      
      if (!alturaMetros || alturaMetros <= 0) {
        setIsDraggingIMC(false);
        setPacienteArrastandoIMC(null);
        return;
      }

      const percentualParaIMC = (percent: number): number => {
        const p = Math.max(0, Math.min(100, percent));
        const IMC_MIN = 14; // limite mínimo (evita zerar ao arrastar)
        if (p <= 25) return IMC_MIN + (p / 25) * (18.5 - IMC_MIN);
        if (p <= 50) {
          const percentualNaFaixa = (p - 25) / 25;
          return 18.5 + (percentualNaFaixa * (25 - 18.5));
        }
        if (p <= 75) {
          const percentualNaFaixa = (p - 50) / 25;
          return 25 + (percentualNaFaixa * (30 - 25));
        }
        const percentualNaFaixa = (p - 75) / 25;
        return 30 + (percentualNaFaixa * 20);
      };

      const imcParaPeso = (imc: number): number => {
        return imc * (alturaMetros * alturaMetros);
      };

      const novoIMC = percentualParaIMC(percentual);
      const novoPeso = imcParaPeso(novoIMC);
      
      setImcTemporarioIMC(novoIMC);
      setPesoTemporarioIMC(novoPeso);
    };

    const handleMouseUp = () => {
      setIsDraggingIMC(false);
      setPacienteArrastandoIMC(null);
      setPesoTemporarioIMC(null);
      setImcTemporarioIMC(null);
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDraggingIMC, pacienteArrastandoIMC, pacientes]);

  // Event listeners para arrastar o marcador de IMC (touch)
  useEffect(() => {
    if (!isDraggingIMC || !pacienteArrastandoIMC) return;

    const handleTouchMove = (e: TouchEvent) => {
      const barraRef = barraIMCRef.current[pacienteArrastandoIMC];
      if (!barraRef) return;
      
      // Só prevenir default se o evento for cancelável
      if (e.cancelable) {
        e.preventDefault();
      }
      
      const rect = barraRef.getBoundingClientRect();
      const touch = e.touches[0];
      const x = touch.clientX - rect.left;
      // Trava nas extremidades: limitar entre 0% e 100%
      const percentual = Math.max(0, Math.min(100, (x / rect.width) * 100));
      
      // Buscar dados do paciente
      const paciente = pacientes.find(p => p.id === pacienteArrastandoIMC);
      if (!paciente) return;
      
      const medidasIniciais = paciente.dadosClinicos?.medidasIniciais;
      const alturaCm = medidasIniciais?.altura;
      const alturaMetros = alturaCm && typeof alturaCm === 'number' && alturaCm > 0 ? alturaCm / 100 : null;
      
      if (!alturaMetros || alturaMetros <= 0) {
        setIsDraggingIMC(false);
        setPacienteArrastandoIMC(null);
        return;
      }

      const percentualParaIMC = (percent: number): number => {
        const p = Math.max(0, Math.min(100, percent));
        const IMC_MIN = 14; // limite mínimo (evita zerar ao arrastar)
        if (p <= 25) return IMC_MIN + (p / 25) * (18.5 - IMC_MIN);
        if (p <= 50) {
          const percentualNaFaixa = (p - 25) / 25;
          return 18.5 + (percentualNaFaixa * (25 - 18.5));
        }
        if (p <= 75) {
          const percentualNaFaixa = (p - 50) / 25;
          return 25 + (percentualNaFaixa * (30 - 25));
        }
        const percentualNaFaixa = (p - 75) / 25;
        return 30 + (percentualNaFaixa * 20);
      };

      const imcParaPeso = (imc: number): number => {
        return imc * (alturaMetros * alturaMetros);
      };

      const novoIMC = percentualParaIMC(percentual);
      const novoPeso = imcParaPeso(novoIMC);
      
      setImcTemporarioIMC(novoIMC);
      setPesoTemporarioIMC(novoPeso);
    };

    const handleTouchEnd = () => {
      setIsDraggingIMC(false);
      setPacienteArrastandoIMC(null);
      setPesoTemporarioIMC(null);
      setImcTemporarioIMC(null);
    };

    window.addEventListener('touchmove', handleTouchMove, { passive: false });
    window.addEventListener('touchend', handleTouchEnd);
    
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [isDraggingIMC, pacienteArrastandoIMC, pacientes]);

  // Efeito para mostrar fogos quando IMC entrar na faixa saudável
  useEffect(() => {
    if (!isDraggingIMC || !pacienteArrastandoIMC || imcTemporarioIMC === null) {
      // Limpar fogos quando não estiver arrastando
      if (!isDraggingIMC && pacienteArrastandoIMC) {
        setShowFireworks(prev => {
          const newState = { ...prev };
          delete newState[pacienteArrastandoIMC];
          return newState;
        });
      }
      return;
    }

    // Verificar se está na faixa saudável (18.5 a 25)
    const isSaudavel = imcTemporarioIMC >= 18.5 && imcTemporarioIMC < 25;
    
    if (isSaudavel) {
      // Ativar fogos para este paciente
      setShowFireworks(prev => ({
        ...prev,
        [pacienteArrastandoIMC]: true
      }));
      
      // Desativar após 3 segundos
      const timer = setTimeout(() => {
        setShowFireworks(prev => {
          const newState = { ...prev };
          delete newState[pacienteArrastandoIMC];
          return newState;
        });
      }, 3000);
      
      return () => clearTimeout(timer);
    } else {
      // Desativar fogos se sair da faixa saudável
      setShowFireworks(prev => {
        const newState = { ...prev };
        delete newState[pacienteArrastandoIMC];
        return newState;
      });
    }
  }, [isDraggingIMC, pacienteArrastandoIMC, imcTemporarioIMC]);

  const [buscaPaciente, setBuscaPaciente] = useState<string>('');
  const [filtroStatusPaciente, setFiltroStatusPaciente] = useState<string>('todos');
  const [ordenacaoPacientesDesktop, setOrdenacaoPacientesDesktop] =
    useState<OrdenacaoColunaPacientesDesktop>('nome');
  const [loadingPacientes, setLoadingPacientes] = useState(false);
  
  // Estados para filtros financeiro
  const [buscaPacienteFinanceiro, setBuscaPacienteFinanceiro] = useState<string>('');
  const [filtroStatusPagamentoFinanceiro, setFiltroStatusPagamentoFinanceiro] = useState<string>('todos');
  const [mostrarDadosFinanceiro, setMostrarDadosFinanceiro] = useState(false);
  const [relatorioFinanceiroTipo, setRelatorioFinanceiroTipo] = useState<FinanceiroRelatorioTipo | null>(null);
  const [filtroAnoDadosFinanceiro, setFiltroAnoDadosFinanceiro] = useState<string | number>('todos');
  const [filtroMesDadosFinanceiro, setFiltroMesDadosFinanceiro] = useState<string | number>('todos');
  const [dadosFinanceiroLinhasExpandidas, setDadosFinanceiroLinhasExpandidas] = useState<Set<string>>(new Set());
  const [financeiroCalendarioMes, setFinanceiroCalendarioMes] = useState(() => {
    const d = new Date();
    return { year: d.getFullYear(), month: d.getMonth() };
  });
  const [financeiroDataCalendarioSelecionada, setFinanceiroDataCalendarioSelecionada] = useState<string | null>(null);
  const [fotosPacientes, setFotosPacientes] = useState<Record<string, string | null>>({});
  // Ref para rastrear se loadPagamentos foi chamado recentemente por loadPacientes
  const loadPagamentosChamadoPorLoadPacientes = useRef(false);
  const loadingMedicoRef = useRef(false);
  const loadingPacientesRef = useRef(false);
  const loadingPagamentosRef = useRef(false);
  const loadingSolicitacoesRef = useRef(false);
  const loadingMensagensRef = useRef(false);
  const loadingLeadsRef = useRef(false);
  const loadingLembretesRef = useRef(false);
  /** Incrementado a cada mutate local; fetch async obsoleto não sobrescreve o estado. */
  const lembretesSyncGenerationRef = useRef(0);
  const npsMedicoVerificadoRef = useRef<string | null>(null);
  // Ref para o container do pipeline de leads (mobile)
  const [npsRespondidoPorPaciente, setNpsRespondidoPorPaciente] = useState<Record<string, boolean>>({});
  const [pacientesComNutricao, setPacientesComNutricao] = useState<Record<string, boolean>>({});
  const [salvandoAlteracoes, setSalvandoAlteracoes] = useState(false);
  const [pagamentosPacientes, setPagamentosPacientes] = useState<Record<string, PagamentoPaciente>>({});
  const pacientesFiltradosOrdenadosDesktop = useMemo(() => {
    const q = normTextoBuscaCal(buscaPaciente);
    const filtrados = pacientes.filter((paciente) => {
      const matchBusca = !q || normTextoBuscaCal(paciente.nome).includes(q);
      const statusPaciente = paciente.statusTratamento || 'pendente';
      const matchStatus = filtroStatusPaciente === 'todos' || statusPaciente === filtroStatusPaciente;
      return matchBusca && matchStatus;
    });
    return sortPacientesListaDesktop(filtrados, ordenacaoPacientesDesktop, pagamentosPacientes);
  }, [pacientes, buscaPaciente, filtroStatusPaciente, ordenacaoPacientesDesktop, pagamentosPacientes]);
  const [vendasAvulsas, setVendasAvulsas] = useState<VendaAvulsa[]>([]);
  const [showModalPagamento, setShowModalPagamento] = useState(false);
  /** 'modal' = overlay global; 'embedded' = aba Financeiro dentro do editar paciente. */
  const [pagamentoUiMode, setPagamentoUiMode] = useState<'modal' | 'embedded'>('modal');
  const [financeiroEmbedEl, setFinanceiroEmbedEl] = useState<HTMLDivElement | null>(null);
  const [cobrancaConfirmTarget, setCobrancaConfirmTarget] = useState<CobrancaConfirmTarget | null>(null);
  const [enviandoCobrancaConfirm, setEnviandoCobrancaConfirm] = useState(false);
  const showModalPagamentoEstavaAbertoRef = useRef(false);
  const [showModalNovaVendaData, setShowModalNovaVendaData] = useState(false);
  const [gerandoRelatorioFinanceiro, setGerandoRelatorioFinanceiro] = useState(false);
  const [showOrcamentoTerapeuticoFlow, setShowOrcamentoTerapeuticoFlow] = useState(false);
  const [novaVendaDataSelecionada, setNovaVendaDataSelecionada] = useState<string>(() => new Date().toISOString().slice(0, 10));
