  const aoMudarJanelaCalendario = useCallback((inicio: Date, fim: Date) => {
    const next = `${inicio.getFullYear()}-${inicio.getMonth()}-${inicio.getDate()}|${fim.getFullYear()}-${fim.getMonth()}-${fim.getDate()}`;
    setCalendarioJanela((prev) => (prev === next ? prev : next));
  }, []);
  /** Filtro por nome do paciente no calendário (grid, painel do dia e aba Dados). */
  const [buscaPacienteCalendario, setBuscaPacienteCalendario] = useState('');
  /** Abre lista de sugestões ao focar o campo de busca do calendário. */
  const [calendarioBuscaDropdownAberto, setCalendarioBuscaDropdownAberto] = useState(false);
  /** Valor adiado: o grid pesado do calendário usa isto para não travar a digitação. */
  const buscaCalendarioDeferida = useDeferredValue(buscaPacienteCalendario);
  const sugestoesListaCalendario = useMemo(() => {
    const q = normTextoBuscaCal(buscaPacienteCalendario);
    if (!q || pacientes.length === 0) return [];
    const matches: string[] = [];
    const seen = new Set<string>();
    for (let i = 0; i < pacientes.length; i++) {
      const p = pacientes[i];
      const nome = (p.nome || p.dadosIdentificacao?.nomeCompleto || '').trim();
      if (!nome) continue;
      const nn = normTextoBuscaCal(nome);
      if (!nn.includes(q)) continue;
      if (seen.has(nome)) continue;
      seen.add(nome);
      matches.push(nome);
    }
    matches.sort((a, b) => {
      const na = normTextoBuscaCal(a);
      const nb = normTextoBuscaCal(b);
      const pa = na.startsWith(q) ? 0 : 1;
      const pb = nb.startsWith(q) ? 0 : 1;
      if (pa !== pb) return pa - pb;
      return a.localeCompare(b, 'pt-BR');
    });
    return matches.slice(0, 10);
  }, [buscaPacienteCalendario, pacientes]);
  const [mostrarDadosCalendario, setMostrarDadosCalendario] = useState(false);
