  // Ícone de contrato na lista mobile: carregar status por paciente
  useEffect(() => {
    if (activeMenu !== 'pacientes' && activeMenu !== 'meus-pacientes') return;
    const ids = pacientes.map((p) => p.id).filter((id): id is string => Boolean(id));
    if (ids.length === 0) {
      setContratoIconByPacienteId({});
      return;
    }

    let cancelled = false;
    const BATCH = 10;

    (async () => {
      for (let i = 0; i < ids.length; i += BATCH) {
        const batch = ids.slice(i, i + BATCH);
        const results = await Promise.all(
          batch.map(async (id) => {
            try {
              const doc = await obterContratoTratamentoAtual(id);
              return [id, resolveContratoListaIconState(doc)] as const;
            } catch {
              return [id, 'nao_gerado' as const] as const;
            }
          })
        );
        if (cancelled) return;
        setContratoIconByPacienteId((prev) => {
          const next = { ...prev };
          for (const [id, state] of results) next[id] = state;
          return next;
        });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [activeMenu, pacientes, contratoIconRefreshKey]);

