  const removerHipoteseDiagnosticaSalva = useCallback(
    async (indice: number) => {
      if (!medicoPerfil?.id) return;
      const atual = medicoPerfil.hipotesesDiagnosticasSalvas || [];
      if (indice < 0 || indice >= atual.length) return;
      const novas = atual.filter((_, i) => i !== indice) as Medico['hipotesesDiagnosticasSalvas'];
      try {
        await MedicoService.updateMedico(medicoPerfil.id, { hipotesesDiagnosticasSalvas: novas });
        setMedicoPerfil({ ...medicoPerfil, hipotesesDiagnosticasSalvas: novas });
      } catch (err) {
        console.error(err);
        setMessage('Erro ao remover hipótese salva.');
      }
    },
    [medicoPerfil]
  );

  const salvarHipoteseDiagnosticaSolicitacao = useCallback(async () => {
    const tit = hipoteseDiagnosticaTituloSalvar.trim();
    const texto = hipoteseDiagnosticaSolicitacao.trim();
    if (!tit || !texto || !medicoPerfil?.id) return;
    setSalvandoHipoteseDiagnostica(true);
    try {
      const atual = normalizeHipotesesDiagnosticasSalvas(medicoPerfil.hipotesesDiagnosticasSalvas);
      const existe = atual.some((x) => x.titulo.trim().toLowerCase() === tit.toLowerCase());
      const novo: HipoteseDiagnosticaSalva = { titulo: tit.slice(0, 120), texto };
      const novas: HipoteseDiagnosticaSalva[] = existe ? atual : [...atual, novo];
      if (!existe) {
        await MedicoService.updateMedico(medicoPerfil.id, { hipotesesDiagnosticasSalvas: novas });
        setMedicoPerfil({ ...medicoPerfil, hipotesesDiagnosticasSalvas: novas });
      }
      setMessage(
        existe
          ? 'Já existe uma hipótese salva com esse título.'
          : 'Hipótese salva para as próximas requisições.'
      );
    } catch (err) {
      console.error(err);
      setMessage('Erro ao salvar hipótese. Tente novamente.');
    } finally {
      setSalvandoHipoteseDiagnostica(false);
    }
  }, [hipoteseDiagnosticaTituloSalvar, hipoteseDiagnosticaSolicitacao, medicoPerfil]);

  const salvarModeloPadraoExames = useCallback(async (nome: string) => {
    const nomeTrim = nome.trim();
    if (!nomeTrim || !medicoPerfil?.id) return;
    const temExames =
      examesSelecionados.length > 0 || examesCustomizados.some((e) => e.trim().length > 0);
    if (!temExames) return;
    setSalvandoModeloPadrao(true);
    try {
      const atual = normalizeModelosPadraoExames(medicoPerfil.modelosPadraoExames);
      const custom = examesCustomizados.map((e) => e.trim()).filter(Boolean);
      const hipoteseTitulo = hipoteseDiagnosticaTituloSalvar.trim();
      const payload: ModeloPadraoExamesSalvo = {
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        nome: nomeTrim.slice(0, 80),
        examesSelecionados: [...examesSelecionados],
        examesCustomizados: custom,
        hipoteseDiagnostica: hipoteseDiagnosticaSolicitacao.trim(),
        hipoteseDiagnosticaTitulo: hipoteseTitulo ? hipoteseTitulo.slice(0, 120) : undefined,
        criadoEm: new Date().toISOString(),
      };
      const idx = atual.findIndex((m) => m.nome.trim().toLowerCase() === nomeTrim.toLowerCase());
      const novas: ModeloPadraoExamesSalvo[] =
        idx >= 0 ? atual.map((m, i) => (i === idx ? { ...payload, id: m.id } : m)) : [...atual, payload];
      await MedicoService.updateMedico(medicoPerfil.id, { modelosPadraoExames: novas });
      setMedicoPerfil({ ...medicoPerfil, modelosPadraoExames: novas });
      setMessage(idx >= 0 ? 'Modelo padrão atualizado.' : 'Modelo padrão salvo.');
    } catch (err) {
      console.error(err);
      setMessage('Erro ao salvar modelo padrão. Tente novamente.');
      throw err;
    } finally {
      setSalvandoModeloPadrao(false);
    }
  }, [
    medicoPerfil,
    examesSelecionados,
    examesCustomizados,
    hipoteseDiagnosticaSolicitacao,
    hipoteseDiagnosticaTituloSalvar,
  ]);

