  const handleAbrirVendaAvulsa = useCallback((venda: VendaAvulsa) => {
    setVendaAvulsaEditando(venda);
    setPagamentoParcialIdx(null);
    setPagamentoParcialValor('');
    const dataVendaNorm =
      venda.dataVenda instanceof Date
        ? venda.dataVenda
        : venda.dataVenda
          ? new Date((venda.dataVenda as { toDate?: () => Date })?.toDate?.() ?? venda.dataVenda)
          : new Date();
    let parcelasEdit = (venda.parcelas || []).map((p, i) => ({ ...p, numero: i + 1 }));
    if (parcelasEdit.length === 0 && (venda.valorTotal || 0) > 0) {
      const venc = venda.dataVencimento
        ? venda.dataVencimento instanceof Date
          ? venda.dataVencimento
          : new Date((venda.dataVencimento as { toDate?: () => Date })?.toDate?.() ?? venda.dataVencimento)
        : (() => {
            const d = new Date(dataVendaNorm);
            d.setMonth(d.getMonth() + 1);
            return d;
          })();
      const pago = venda.valorPago || 0;
      const total = venda.valorTotal || 0;
      if (pago > 0 && pago < total) {
        parcelasEdit = [
          {
            numero: 1,
            valor: pago,
            dataVencimento: venc,
            dataPagamento: venda.dataPagamento
              ? venda.dataPagamento instanceof Date
                ? venda.dataPagamento
                : new Date((venda.dataPagamento as { toDate?: () => Date })?.toDate?.() ?? venda.dataPagamento)
              : new Date(),
            status: 'paga',
          },
          {
            numero: 2,
            valor: total - pago,
            dataVencimento: venc,
            status: 'pendente',
          },
        ];
      } else {
        parcelasEdit = [
          {
            numero: 1,
            valor: total,
            dataVencimento: venc,
            dataPagamento:
              pago >= total
                ? venda.dataPagamento
                  ? venda.dataPagamento instanceof Date
                    ? venda.dataPagamento
                    : new Date((venda.dataPagamento as { toDate?: () => Date })?.toDate?.() ?? venda.dataPagamento)
                  : new Date()
                : undefined,
            status: pago >= total ? 'paga' : 'pendente',
          },
        ];
      }
    }
    const totais = recalcularTotaisParcelas(parcelasEdit);
    setDadosVendaAvulsa({
      descricao: venda.descricao,
      cliente: venda.cliente || '',
      statusPagamento: venda.statusPagamento,
      formaPagamento: parcelasEdit.length > 1 ? 'dividido' : venda.formaPagamento || 'a_vista',
      valorTotal: totais.valorTotal || venda.valorTotal,
      valorPago: totais.valorPago || venda.valorPago,
      valorPendente: totais.valorPendente || venda.valorPendente,
      parcelas: parcelasEdit,
      observacoes: venda.observacoes || '',
      observacaoVenda: venda.observacaoVenda,
      dataVenda: dataVendaNorm,
      dataVencimento: venda.dataVencimento,
      dataPagamento: venda.dataPagamento,
    });
    setShowModalVendaAvulsa(true);
  }, []);

  const enviarCobrancaWhatsappConfirmada = useCallback(
    async (target: CobrancaConfirmTarget) => {
      const currentUser = auth.currentUser ?? user;
      if (!currentUser) {
        setMessage('Sessão indisponível. Faça login novamente.');
        return;
      }
      setEnviandoCobrancaConfirm(true);
      try {
        const token = await currentUser.getIdToken();
        const res = await fetch('/api/metaadmin/financeiro/cobranca-whatsapp', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            pacienteId: target.pacienteId,
            valorAberto: target.valorAberto,
          }),
        });
        const data = (await res.json().catch(() => null)) as {
          ok?: boolean;
          error?: string;
          message?: string;
          status?: CobrancaSubmitStatus;
        } | null;
        if (!res.ok || data?.ok === false) {
          setMessage(data?.error || 'Não foi possível enviar a cobrança.');
          return;
        }
        if (data?.status === 'confirmation_sent' || data?.status === 'awaiting_confirmation') {
          setMessage(
            data.message ||
              'Confirmação enviada. A cobrança será enviada automaticamente após o paciente responder OK no Canal Chat.',
          );
        } else {
          setMessage(data?.message || `Cobrança enviada para ${target.pacienteNome}.`);
        }
        setCobrancaConfirmTarget(null);
        return data?.status === 'confirmation_sent' || data?.status === 'awaiting_confirmation'
          ? data.status
          : 'sent';
      } catch (error) {
        console.error('Erro ao enviar cobrança:', error);
        setMessage('Erro ao enviar cobrança pelo Canal Chat.');
      } finally {
        setEnviandoCobrancaConfirm(false);
      }
    },
    [user]
  );

