  const abrirPrescricaoDoHistoricoParaEditar = useCallback((p: Prescricao, destino: 'desktop' | 'modal' = 'modal') => {
    const form = prescricaoFormFromEntity(p);
    if (destino === 'desktop') {
      setPrescricaoSelecionada(p);
      setPrescricaoEditando(p);
      setNovaPrescricao(form);
    } else {
      setPrescricaoSelecionadaModal(p);
      setPrescricaoEditandoModal(p);
      setNovaPrescricaoModal(form);
    }
    if (destino !== 'desktop') {
      setAbaPrescricoesModal('descricao');
    }
  }, []);

  const abrirPrescricaoDoHistoricoComoNova = useCallback((p: Prescricao, paciente: PacienteCompleto, destino: 'desktop' | 'modal' = 'modal') => {
    const temp: Prescricao = {
      ...p,
      id: 'temp-new',
      pacienteId: paciente.id,
      pacienteNome: paciente.dadosIdentificacao?.nomeCompleto || paciente.nome,
      isTemplate: false,
      criadoEm: new Date(),
      atualizadoEm: new Date(),
      criadoPor: user?.email || p.criadoPor || '',
    };
    const form = prescricaoFormFromEntity(temp);
    const isProtocolo = p.catalogoAba === 'protocolo';
    if (destino === 'desktop') {
      if (isProtocolo) {
        setProtocolos((prev) => [temp, ...(prev || []).filter((x) => x.id !== 'temp-new')]);
        setSubAbaPrescricoesDesktop('protocolos');
      } else {
        setPrescricoes((prev) => [temp, ...(prev || []).filter((x) => x.id !== 'temp-new')]);
        setSubAbaPrescricoesDesktop('prescricoes');
      }
      setPrescricaoSelecionada(temp);
      setPrescricaoEditando(null);
      setNovaPrescricao(form);
    } else {
      if (isProtocolo) {
        setProtocolosModal((prev) => [temp, ...prev.filter((x) => x.id !== 'temp-new')]);
        setSubAbaPrescricoesDesktop('protocolos');
      } else {
        setPrescricoesModal((prev) => [temp, ...prev.filter((x) => x.id !== 'temp-new')]);
        setSubAbaPrescricoesDesktop('prescricoes');
      }
      setPrescricaoSelecionadaModal(temp);
      setPrescricaoEditandoModal(null);
      setNovaPrescricaoModal(form);
    }
    if (destino !== 'desktop') {
      setAbaPrescricoesModal('descricao');
    }
  }, [user?.email]);

  const abrirPrescricaoDaBusca = useCallback(
    (p: Prescricao, destino: 'desktop' | 'modal') => {
      const paciente = destino === 'desktop' ? pacienteEditando : pacientePrescricoesSelecionado;
      if (!paciente) return;
      let fonte = p;
      if (p.isTemplate && prescricaoTemSuplementoPorPeso(p)) {
        const peso =
          paciente.dadosClinicos?.medidasIniciais?.peso ||
          paciente.evolucaoSeguimento?.[paciente.evolucaoSeguimento.length - 1]?.peso;
        if (!peso) {
          setMessage(
            destino === 'desktop'
              ? 'Peso do paciente não encontrado. Por favor, cadastre o peso nas Medidas Iniciais (aba Anamnese).'
              : 'Cadastre o peso do paciente (Anamnese ou Evolução).'
          );
          setTimeout(() => setMessage(''), 5000);
          return;
        }
        fonte = aplicarTemplatePrescricaoParaPeso(p, peso);
      }
      abrirPrescricaoDoHistoricoComoNova(fonte, paciente, destino);
    },
    [pacienteEditando, pacientePrescricoesSelecionado, abrirPrescricaoDoHistoricoComoNova]
  );

  const irParaDescricaoForaDoSplitDesktop = useCallback(() => {
    if (typeof window !== 'undefined' && window.matchMedia('(min-width: 1024px)').matches) return;
    setAbaPrescricoesModal('descricao');
  }, []);

  useEffect(() => {
    if (pastaAtiva !== 9) return;
    // Não sobrescrever seleção vinda do Histórico (paciente) ou rascunho "Usar como nova"
    const sel = prescricaoSelecionada;
    if (sel && (sel.id === 'temp-new' || (Boolean(sel.pacienteId) && !sel.isTemplate))) {
      return;
    }
    if (subAbaPrescricoesDesktop === 'prescricoes') {
      if (prescricoes.length === 0) {
        setPrescricaoSelecionada(null);
        setPrescricaoEditando(null);
        return;
      }
      if (!prescricoes.some((p) => p.id === sel?.id)) {
        const primeira = prescricoes[0];
        setPrescricaoSelecionada(primeira);
        setPrescricaoEditando(primeira.isTemplate ? null : primeira);
        setNovaPrescricao(prescricaoFormFromEntity(primeira));
      }
      return;
    }
    if (protocolos.length === 0) {
      setPrescricaoSelecionada(null);
      setPrescricaoEditando(null);
      return;
    }
    if (!protocolos.some((p) => p.id === sel?.id)) {
      const primeira = protocolos[0];
      setPrescricaoSelecionada(primeira);
      setPrescricaoEditando(primeira.isTemplate ? null : primeira);
      setNovaPrescricao(prescricaoFormFromEntity(primeira));
    }
  }, [subAbaPrescricoesDesktop, prescricoes, protocolos, pastaAtiva, prescricaoSelecionada]);

  /** Salva a prescrição atual para o paciente (Pasta 9). Usado pelo botão Salvar e pelo fluxo de impressão. */
  const salvarPrescricaoAtualPastaPaciente = useCallback(async (): Promise<{ ok: boolean; prescricaoSalva?: Prescricao | null }> => {
    if (!medicoPerfil || !pacienteEditando) {
      return { ok: false };
    }
    if (!novaPrescricao.nome.trim()) {
      setMessage('Nome da prescrição é obrigatório');
      setTimeout(() => setMessage(''), 3000);
      return { ok: false };
    }

    const isReciboSalvar = isReciboMedicoPrescricao(prescricaoSelecionada);
    const isTextoLivreSalvar = isConteudoTextoLivrePrescricao(prescricaoSelecionada);
    let valorRecibo: number | undefined;
    let dataIsoRecibo = '';
    if (isReciboSalvar) {
      if (!novaPrescricao.descricao.trim()) {
        setMessage('Descrição da consulta é obrigatória');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
      const v = parseValorConsultaBRLInput(novaPrescricao.valorConsulta);
      if (v === null) {
        setMessage('Informe um valor válido (ex.: 350 ou 350,00)');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
      valorRecibo = v;
      dataIsoRecibo = (novaPrescricao.dataRecibo || '').trim();
      if (!isDataReciboISOValid(dataIsoRecibo)) {
        setMessage('Informe a data do recibo.');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
    } else if (isTextoLivreSalvar) {
      if (!novaPrescricao.descricao.trim()) {
        setMessage('Escreva o conteúdo da prescrição.');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
    } else {
      if (!novaPrescricao.itens || novaPrescricao.itens.length === 0) {
        setMessage('Adicione pelo menos um item à prescrição');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
      for (const item of novaPrescricao.itens || []) {
        if (!item.medicamento.trim() || !item.dosagem.trim() || !item.frequencia.trim() || !item.instrucoes.trim()) {
          setMessage('Preencha todos os campos obrigatórios dos itens');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
      }
    }

    try {
      const pesoAtual =
        pacienteEditando.dadosClinicos?.medidasIniciais?.peso ||
        pacienteEditando.evolucaoSeguimento?.[pacienteEditando.evolucaoSeguimento.length - 1]?.peso;

      const isTemporaria = prescricaoSelecionada?.id === 'temp-new';
      const pacienteIdCtx = (pacienteEditando.id || '').trim();
      const pacienteNomeCtx =
        pacienteEditando.dadosIdentificacao?.nomeCompleto || pacienteEditando.nome || '';

      // Só atualiza se já for doc do histórico deste paciente.
      // Catálogo / template / +Nova → sempre cria cópia com pacienteId (não vaza para outros pacientes).
      const atualizarHistoricoPaciente = Boolean(
        prescricaoEditando &&
          !prescricaoEditando.isTemplate &&
          !isTemporaria &&
          (prescricaoEditando.pacienteId || '').trim() === pacienteIdCtx &&
          !!pacienteIdCtx
      );

      const catalogoAbaSalvar =
        prescricaoSelecionada?.catalogoAba ||
        (subAbaPrescricoesDesktop === 'protocolos' ? 'protocolo' : 'prescricao');
      const pastaIdSalvar = prescricaoSelecionada?.pastaId;
      const pastaNomeSalvar = prescricaoSelecionada?.pastaNome;
      const atualizarProtocoloCatalogo = Boolean(
        catalogoAbaSalvar === 'protocolo' &&
          !isTemporaria &&
          isProtocoloCatalogoProprioMedico(prescricaoEditando, medicoPerfil.id)
      );
      const destinoSalvar = resolverDestinoSalvarPrescricao({
        catalogoAba: catalogoAbaSalvar,
        atualizarHistoricoPaciente,
        atualizarProtocoloCatalogo,
      });

      const extrasReciboSalvar = isReciboSalvar
        ? {
            tipoDocumento: 'recibo_medico' as const,
            valorConsulta: valorRecibo,
            dataRecibo: dataIsoRecibo,
            reciboDocumentoProfissional: novaPrescricao.reciboDocumentoProfissional,
          }
        : {};

      const prescricaoData: Omit<Prescricao, 'id'> | Prescricao =
        destinoSalvar === 'atualizar' && atualizarHistoricoPaciente
          ? {
              ...prescricaoEditando!,
              pacienteId: pacienteIdCtx,
              pacienteNome: pacienteNomeCtx,
              nome: novaPrescricao.nome,
              descricao: novaPrescricao.descricao,
              itens: isReciboSalvar || isTextoLivreSalvar ? [] : novaPrescricao.itens,
              observacoes: novaPrescricao.observacoes,
              atualizadoEm: new Date(),
              ...extrasReciboSalvar,
            }
          : destinoSalvar === 'atualizar' && atualizarProtocoloCatalogo
            ? (() => {
                const { pacienteId: _omitPid, pacienteNome: _omitPn, ...rest } = prescricaoEditando!;
                return {
                  ...rest,
                  nome: novaPrescricao.nome,
                  descricao: novaPrescricao.descricao,
                  itens: isReciboSalvar || isTextoLivreSalvar ? [] : novaPrescricao.itens,
                  observacoes: novaPrescricao.observacoes,
                  atualizadoEm: new Date(),
                  isTemplate: false,
                  catalogoAba: 'protocolo' as const,
                  medicoId: medicoPerfil.id,
                };
              })()
            : destinoSalvar === 'catalogo_protocolo'
              ? {
                  medicoId: medicoPerfil.id,
                  nome: novaPrescricao.nome,
                  descricao: novaPrescricao.descricao,
                  itens: isReciboSalvar || isTextoLivreSalvar ? [] : novaPrescricao.itens,
                  observacoes: novaPrescricao.observacoes,
                  criadoEm: new Date(),
                  atualizadoEm: new Date(),
                  criadoPor: user?.email || '',
                  isTemplate: false,
                  catalogoAba: 'protocolo' as const,
                  ...(pastaIdSalvar ? { pastaId: pastaIdSalvar } : {}),
                  ...(pastaNomeSalvar ? { pastaNome: pastaNomeSalvar } : {}),
                }
              : {
                  medicoId: medicoPerfil.id,
                  pacienteId: pacienteIdCtx,
                  pacienteNome: pacienteNomeCtx,
                  nome: novaPrescricao.nome,
                  descricao: novaPrescricao.descricao,
                  itens: isReciboSalvar || isTextoLivreSalvar ? [] : novaPrescricao.itens,
                  observacoes: novaPrescricao.observacoes,
                  criadoEm: new Date(),
                  atualizadoEm: new Date(),
                  criadoPor: user?.email || '',
                  isTemplate: false,
                  catalogoAba: catalogoAbaSalvar,
                  ...(pastaIdSalvar ? { pastaId: pastaIdSalvar } : {}),
                  ...(pastaNomeSalvar ? { pastaNome: pastaNomeSalvar } : {}),
                  pesoPaciente: isReciboSalvar ? undefined : pesoAtual,
                  ...extrasReciboSalvar,
                };

      if (!pacienteIdCtx) {
        setMessage('Paciente inválido para salvar a prescrição.');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }

      const prescricaoId = await PrescricaoService.createOrUpdatePrescricao(prescricaoData);

      if (!prescricaoId || typeof prescricaoId !== 'string') {
        setMessage('Não foi possível gravar a prescrição. Tente novamente.');
        setTimeout(() => setMessage(''), 4000);
        return { ok: false };
      }

      if (prescricaoSelecionada?.id === 'temp-new') {
        setPrescricoes((prev) => (prev || []).filter((p) => p.id !== 'temp-new'));
        setProtocolos((prev) => (prev || []).filter((p) => p.id !== 'temp-new'));
      }

      await loadPrescricoes();

      let prescricaoSalva: Prescricao | null = await PrescricaoService.getPrescricaoById(prescricaoId);
      if (!prescricaoSalva) {
        await new Promise((r) => setTimeout(r, 400));
        prescricaoSalva = await PrescricaoService.getPrescricaoById(prescricaoId);
      }
      if (!prescricaoSalva) {
        const [templates, prescricoesMedico] = await Promise.all([
          PrescricaoService.getPrescricoesTemplate(),
          PrescricaoService.getPrescricoesByMedico(medicoPerfil.id),
        ]);
        const todasPrescricoes = [
          ...montarListaPrescricoesAba(templates, prescricoesMedico),
          ...montarListaProtocolosAba(templates, prescricoesMedico),
        ];
        prescricaoSalva = todasPrescricoes.find((p) => p.id === prescricaoId) || null;
      }
      if (prescricaoSalva && !prescricaoSalva.pacienteId) {
        setPrescricaoSelecionada(prescricaoSalva);
        setPrescricaoEditando(prescricaoSalva);
        setNovaPrescricao(prescricaoFormFromEntity(prescricaoSalva));
      }

      // Prescrição: histórico do paciente. Protocolo: catálogo do médico (lista de Injetáveis).
      const salvouNoHistorico = Boolean(
        prescricaoSalva?.pacienteId || (prescricaoData as Prescricao).pacienteId
      );
      if (salvouNoHistorico) {
        setHistoricoPrescricoesRefreshKey((k) => k + 1);
        setAbaPrescricoesModal('historico');
      }

      setMessage(
        salvouNoHistorico
          ? 'Prescrição salva no histórico!'
          : destinoSalvar === 'catalogo_protocolo' ||
              (destinoSalvar === 'atualizar' && atualizarProtocoloCatalogo)
            ? atualizarProtocoloCatalogo
              ? 'Protocolo atualizado! Ele aparece na aba Injetáveis.'
              : 'Protocolo salvo! Ele aparece na lista da aba Injetáveis.'
            : prescricaoEditando && !prescricaoEditando.isTemplate && !isTemporaria
              ? 'Prescrição atualizada com sucesso!'
              : 'Prescrição criada com sucesso!'
      );
      setTimeout(() => setMessage(''), 3000);

      if (prescricaoEditando && !prescricaoEditando.isTemplate && !isTemporaria) {
        const prescricaoAtualizada = {
          ...prescricaoEditando,
          nome: novaPrescricao.nome,
          descricao: novaPrescricao.descricao,
          itens: isReciboSalvar || isTextoLivreSalvar ? [] : novaPrescricao.itens,
          observacoes: novaPrescricao.observacoes,
          ...(isReciboSalvar
            ? {
                tipoDocumento: 'recibo_medico' as const,
                valorConsulta: valorRecibo,
                dataRecibo: dataIsoRecibo,
                reciboDocumentoProfissional: novaPrescricao.reciboDocumentoProfissional,
              }
            : {}),
        };
        setPrescricaoSelecionada(prescricaoAtualizada);
      }

      return { ok: true, prescricaoSalva };
    } catch (error) {
      console.error('Erro ao salvar prescrição:', error);
      setMessage('Erro ao salvar prescrição');
      setTimeout(() => setMessage(''), 3000);
      return { ok: false };
    }
  }, [medicoPerfil, pacienteEditando, prescricaoEditando, prescricaoSelecionada, novaPrescricao, user, loadPrescricoes, subAbaPrescricoesDesktop]);

  /** Salva prescrição no modal mobile (mesma regra do botão Salvar). Usado também antes de Imprimir. */
  const salvarPrescricaoAtualModalPaciente = useCallback(
    async (opts?: { skipSuccessMessage?: boolean }): Promise<{ ok: boolean; prescricaoSalva?: Prescricao | null }> => {
      if (!medicoPerfil || !pacientePrescricoesSelecionado || !prescricaoSelecionadaModal) {
        return { ok: false };
      }
      if (!novaPrescricaoModal.nome.trim()) {
        setMessage('Nome obrigatório');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
      const isRecMob = isReciboMedicoPrescricao(prescricaoSelecionadaModal);
      const isTextoLivreMob = isConteudoTextoLivrePrescricao(prescricaoSelecionadaModal);
      let valorRecMob: number | undefined;
      let dataIsoRecMob = '';
      if (isRecMob) {
        if (!novaPrescricaoModal.descricao.trim()) {
          setMessage('Descrição da consulta é obrigatória');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
        const v = parseValorConsultaBRLInput(novaPrescricaoModal.valorConsulta);
        if (v === null) {
          setMessage('Informe um valor válido (ex.: 350 ou 350,00)');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
        valorRecMob = v;
        dataIsoRecMob = (novaPrescricaoModal.dataRecibo || '').trim();
        if (!isDataReciboISOValid(dataIsoRecMob)) {
          setMessage('Informe a data do recibo.');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
      } else if (isTextoLivreMob) {
        if (!novaPrescricaoModal.descricao.trim()) {
          setMessage('Escreva o conteúdo da prescrição.');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
      } else {
        if (!novaPrescricaoModal.itens?.length) {
          setMessage('Adicione pelo menos um item');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
        for (const it of novaPrescricaoModal.itens || []) {
          if (!it.medicamento?.trim() || !it.dosagem?.trim() || !it.frequencia?.trim() || !it.instrucoes?.trim()) {
            setMessage('Preencha todos os campos dos itens');
            setTimeout(() => setMessage(''), 3000);
            return { ok: false };
          }
        }
      }
      try {
        const isTemp = prescricaoSelecionadaModal?.id === 'temp-new';
        const pacienteIdCtx = (pacientePrescricoesSelecionado.id || '').trim();
        const pacienteNomeCtx =
          pacientePrescricoesSelecionado.dadosIdentificacao?.nomeCompleto ||
          pacientePrescricoesSelecionado.nome ||
          '';
        const atualizarHistoricoPaciente = Boolean(
          prescricaoEditandoModal &&
            !prescricaoEditandoModal.isTemplate &&
            !isTemp &&
            (prescricaoEditandoModal.pacienteId || '').trim() === pacienteIdCtx &&
            !!pacienteIdCtx
        );
        const catalogoAbaSalvar =
          prescricaoSelecionadaModal?.catalogoAba ||
          (subAbaPrescricoesDesktop === 'protocolos' ? 'protocolo' : 'prescricao');
        const pastaIdSalvar = prescricaoSelecionadaModal?.pastaId;
        const pastaNomeSalvar = prescricaoSelecionadaModal?.pastaNome;
        const atualizarProtocoloCatalogo = Boolean(
          catalogoAbaSalvar === 'protocolo' &&
            !isTemp &&
            isProtocoloCatalogoProprioMedico(prescricaoEditandoModal, medicoPerfil.id)
        );
        const destinoSalvar = resolverDestinoSalvarPrescricao({
          catalogoAba: catalogoAbaSalvar,
          atualizarHistoricoPaciente,
          atualizarProtocoloCatalogo,
        });
        const peso =
          pacientePrescricoesSelecionado.dadosClinicos?.medidasIniciais?.peso ??
          pacientePrescricoesSelecionado.evolucaoSeguimento?.[
            (pacientePrescricoesSelecionado.evolucaoSeguimento?.length ?? 0) - 1
          ]?.peso;
        if (!pacienteIdCtx) {
          setMessage('Paciente inválido para salvar a prescrição.');
          setTimeout(() => setMessage(''), 3000);
          return { ok: false };
        }
        const extrasRecMob = isRecMob
          ? {
              tipoDocumento: 'recibo_medico' as const,
              valorConsulta: valorRecMob,
              dataRecibo: dataIsoRecMob,
              reciboDocumentoProfissional: novaPrescricaoModal.reciboDocumentoProfissional,
            }
          : {};
        const data: Omit<Prescricao, 'id'> | Prescricao =
          destinoSalvar === 'atualizar' && atualizarHistoricoPaciente
            ? {
                ...prescricaoEditandoModal!,
                pacienteId: pacienteIdCtx,
                pacienteNome: pacienteNomeCtx,
                nome: novaPrescricaoModal.nome,
                descricao: novaPrescricaoModal.descricao,
                itens: isRecMob || isTextoLivreMob ? [] : novaPrescricaoModal.itens,
                observacoes: novaPrescricaoModal.observacoes,
                atualizadoEm: new Date(),
                ...extrasRecMob,
              }
            : destinoSalvar === 'atualizar' && atualizarProtocoloCatalogo
              ? (() => {
                  const { pacienteId: _omitPid, pacienteNome: _omitPn, ...rest } =
                    prescricaoEditandoModal!;
                  return {
                    ...rest,
                    nome: novaPrescricaoModal.nome,
                    descricao: novaPrescricaoModal.descricao,
                    itens: isRecMob || isTextoLivreMob ? [] : novaPrescricaoModal.itens,
                    observacoes: novaPrescricaoModal.observacoes,
                    atualizadoEm: new Date(),
                    isTemplate: false,
                    catalogoAba: 'protocolo' as const,
                    medicoId: medicoPerfil.id,
                  };
                })()
              : destinoSalvar === 'catalogo_protocolo'
                ? {
                    medicoId: medicoPerfil.id,
                    nome: novaPrescricaoModal.nome,
                    descricao: novaPrescricaoModal.descricao,
                    itens: isRecMob || isTextoLivreMob ? [] : novaPrescricaoModal.itens,
                    observacoes: novaPrescricaoModal.observacoes,
                    criadoEm: new Date(),
                    atualizadoEm: new Date(),
                    criadoPor: user?.email || '',
                    isTemplate: false,
                    catalogoAba: 'protocolo' as const,
                    ...(pastaIdSalvar ? { pastaId: pastaIdSalvar } : {}),
                    ...(pastaNomeSalvar ? { pastaNome: pastaNomeSalvar } : {}),
                  }
                : {
                    medicoId: medicoPerfil.id,
                    pacienteId: pacienteIdCtx,
                    pacienteNome: pacienteNomeCtx,
                    nome: novaPrescricaoModal.nome,
                    descricao: novaPrescricaoModal.descricao,
                    itens: isRecMob || isTextoLivreMob ? [] : novaPrescricaoModal.itens,
                    observacoes: novaPrescricaoModal.observacoes,
                    criadoEm: new Date(),
                    atualizadoEm: new Date(),
                    criadoPor: user?.email || '',
                    isTemplate: false,
                    catalogoAba: catalogoAbaSalvar,
                    ...(pastaIdSalvar ? { pastaId: pastaIdSalvar } : {}),
                    ...(pastaNomeSalvar ? { pastaNome: pastaNomeSalvar } : {}),
                    pesoPaciente: isRecMob ? undefined : peso ?? undefined,
                    ...extrasRecMob,
                  };
        const id = await PrescricaoService.createOrUpdatePrescricao(data);
        if (!id || typeof id !== 'string') {
          setMessage('Não foi possível gravar a prescrição. Tente novamente.');
          setTimeout(() => setMessage(''), 4000);
          return { ok: false };
        }
        if (isTemp) {
          setPrescricoesModal((prev) => prev.filter((x) => x.id !== 'temp-new'));
          setProtocolosModal((prev) => prev.filter((x) => x.id !== 'temp-new'));
        }
        await loadPrescricoesModal(pacientePrescricoesSelecionado);
        let prescricaoSalva: Prescricao | null = await PrescricaoService.getPrescricaoById(id);
        if (!prescricaoSalva) {
          await new Promise((r) => setTimeout(r, 400));
          prescricaoSalva = await PrescricaoService.getPrescricaoById(id);
        }
        if (!prescricaoSalva) {
          const [tpl, med] = await Promise.all([
            PrescricaoService.getPrescricoesTemplate(),
            PrescricaoService.getPrescricoesByMedico(medicoPerfil.id),
          ]);
          const todas = [
            ...montarListaPrescricoesAba(tpl, med),
            ...montarListaProtocolosAba(tpl, med),
          ];
          prescricaoSalva = todas.find((x) => x.id === id) || null;
        }
        if (prescricaoSalva && !prescricaoSalva.pacienteId) {
          setPrescricaoSelecionadaModal(prescricaoSalva);
          setPrescricaoEditandoModal(prescricaoSalva);
          setNovaPrescricaoModal(prescricaoFormFromEntity(prescricaoSalva));
        }
        const salvouNoHistorico = Boolean(prescricaoSalva?.pacienteId || (data as Prescricao).pacienteId);
        if (salvouNoHistorico) {
          setHistoricoPrescricoesRefreshKey((k) => k + 1);
          setAbaPrescricoesModal('historico');
        }
        if (!opts?.skipSuccessMessage) {
          setMessage(
            salvouNoHistorico
              ? 'Prescrição salva no histórico!'
              : destinoSalvar === 'catalogo_protocolo' ||
                  (destinoSalvar === 'atualizar' && atualizarProtocoloCatalogo)
                ? atualizarProtocoloCatalogo
                  ? 'Protocolo atualizado! Ele aparece na aba Injetáveis.'
                  : 'Protocolo salvo! Ele aparece na lista da aba Injetáveis.'
                : isTemp || !prescricaoEditandoModal
                  ? 'Prescrição criada!'
                  : 'Prescrição atualizada!'
          );
          setTimeout(() => setMessage(''), 3000);
        }
        return { ok: true, prescricaoSalva };
      } catch (e) {
        console.error(e);
        setMessage('Erro ao salvar prescrição');
        setTimeout(() => setMessage(''), 3000);
        return { ok: false };
      }
    },
    [
      medicoPerfil,
      pacientePrescricoesSelecionado,
      prescricaoSelecionadaModal,
      prescricaoEditandoModal,
      novaPrescricaoModal,
      user,
      loadPrescricoesModal,
      subAbaPrescricoesDesktop,
    ]
  );

