  const abrirImpressaoSolicitacaoExames = useCallback(async () => {
    if (!medicoPerfil) return;
    const paciente =
      pacienteSolicitarExames ??
      (isMobile ? pacienteExamesSelecionado ?? pacienteEditando : pacienteEditando ?? pacienteExamesSelecionado);
    if (!paciente) return;
    const temExames =
      examesSelecionados.length > 0 || examesCustomizados.some((e) => e.trim().length > 0);
    if (!temExames) return;

    const buildPdfContext = (language: PrescriptionPrintLanguage = 'pt'): SolicitacaoExamesPdfContext => {
      const locale = language === 'en' ? 'en-GB' : 'pt-BR';
      const dataNasc = paciente.dadosIdentificacao?.dataNascimento
        ? new Date(paciente.dadosIdentificacao.dataNascimento).toLocaleDateString(locale)
        : 'N/A';
      const sexoBiologico = paciente.dadosIdentificacao?.sexoBiologico;
      const sexo =
        language === 'en'
          ? sexoBiologico === 'M'
            ? 'Male'
            : sexoBiologico === 'F'
              ? 'Female'
              : 'N/A'
          : sexoBiologico === 'M'
            ? 'Masculino'
            : sexoBiologico === 'F'
              ? 'Feminino'
              : 'N/A';
      return {
        pacienteNome: paciente.dadosIdentificacao?.nome || paciente.nome || 'N/A',
        pacienteCpf: paciente.dadosIdentificacao?.cpf,
        pacienteDataNascimento: dataNasc,
        pacienteSexo: sexo,
      };
    };

    const todosExames = coletarTodosExamesParaSolicitacaoPdf(
      examesSelecionados,
      examesCustomizados,
      paciente.dadosIdentificacao?.sexoBiologico as Sex,
      paciente.dadosIdentificacao?.dataNascimento,
      labLimitOverrides
    );

    // Salva o rascunho antes do modal de PDF / OAuth BRy, para não perder a seleção
    // se o médico for redirecionado para autenticar a assinatura digital.
    let rascunhoId: string | null = null;
    try {
      const rascunhoRef = await addDoc(collection(db, 'pacientes_completos', paciente.id, 'solicitacoesExames'), {
        medicoId: medicoPerfil.id,
        exames: todosExames,
        hipoteseDiagnostica: hipoteseDiagnosticaSolicitacao.trim(),
        criadoEm: serverTimestamp(),
      });
      rascunhoId = rascunhoRef.id;
      setSolicitacoesExamesRefreshKey((k) => k + 1);
    } catch (e) {
      console.error('[SolicitacaoExames] Erro ao salvar rascunho:', e);
    }

    const aposSucessoGeracao = () => {
      setExamesSelecionados([]);
      setExamesCustomizados(['']);
      setSolicitacoesExamesRefreshKey((k) => k + 1);
      setMessage('Requisição salva com data e hora. PDF gerado com sucesso!');
    };

    const textoNoIdioma = async (
      language: PrescriptionPrintLanguage,
      onProgress?: (phase: 'translating' | 'generating_pdf' | 'submitting_signature') => void
    ) => {
      if (language !== 'en') {
        return { exames: todosExames, hipoteseDiagnostica: hipoteseDiagnosticaSolicitacao };
      }
      onProgress?.('translating');
      return requestTraduzirSolicitacaoExames({
        patientId: paciente.id,
        texto: {
          exames: todosExames,
          hipoteseDiagnostica: hipoteseDiagnosticaSolicitacao,
        },
      });
    };

    setExamRequestPrintGate({
      unsigned: async (language = 'pt') => {
        const ctx = buildPdfContext(language);
        const traduzido = await textoNoIdioma(language);
        const doc = await buildSolicitacaoExamesJsPdfDocument(
          {
            exames: traduzido.exames,
            hipoteseDiagnostica: traduzido.hipoteseDiagnostica,
            medico: medicoParaPdf,
            ctx,
          },
          { omitManualSignatureBlock: false, language }
        );
        saveSolicitacaoExamesPdf(doc, ctx.pacienteNome, language);
        aposSucessoGeracao();
      },
      signed: async (onProgress, language = 'pt') => {
        const ctx = buildPdfContext(language);
        const traduzido = await textoNoIdioma(language, onProgress);
        const result = await runExamRequestSignedPrint({
          patientId: paciente.id,
          exames: traduzido.exames,
          hipoteseDiagnostica: traduzido.hipoteseDiagnostica,
          medico: medicoParaPdf,
          ctx,
          providerConfig: doctorSignatureProviderForPrint,
          language,
          onProgress,
        });
        if (result.outcome === 'opened') {
          if (rascunhoId && result.signedPdfUrl) {
            try {
              await updateDoc(
                doc(db, 'pacientes_completos', paciente.id, 'solicitacoesExames', rascunhoId),
                {
                  signedPdfUrl: result.signedPdfUrl,
                  pdfAssinadoEm: serverTimestamp(),
                }
              );
            } catch (e) {
              console.error('[SolicitacaoExames] Erro ao salvar PDF assinado:', e);
            }
          }
          aposSucessoGeracao();
        }
        return result;
      },
    });
  }, [
    medicoParaPdf,
    medicoPerfil,
    pacienteSolicitarExames,
    pacienteEditando,
    pacienteExamesSelecionado,
    examesSelecionados,
    examesCustomizados,
    hipoteseDiagnosticaSolicitacao,
    labLimitOverrides,
    doctorSignatureProviderForPrint,
    isMobile,
  ]);

