                          'aceita': 'bg-green-600 text-white',
                          'rejeitada': 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200',
                          'cancelada': 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300'
